from collections import defaultdict
from itertools import product
from fractions import Fraction

def add(a,b,scale=1):
 d=defaultdict(int,a)
 for w,v in b.items():d[w]+=scale*v
 return {w:v for w,v in d.items() if v}
def mul(a,b):
 d=defaultdict(int)
 for u,x in a.items():
  for v,y in b.items():d[u+v]+=x*y
 return {w:v for w,v in d.items() if v}
def bracket(a,b):return add(mul(a,b),mul(b,a),-1)
def deriv(D,a):
 out={}
 for w,v in a.items():
  for k,x in enumerate(w):
   out=add(out,{w[:k]+u+w[k+1:]:v*z for u,z in D[x].items()})
 return out
def dbracket(D,E):return tuple(add(deriv(D,e),deriv(E,d),-1) for d,e in zip(D,E))
def generators(n):
 X=[{(i,):1} for i in range(n)]; G=[]
 for i in range(n):
  for j in range(n):
   for k in range(j+1,n):
    D=[{} for _ in range(n)];D[i]=bracket(X[j],X[k]);G.append(tuple(D))
 return G
def rank(ds,p=1000003):
 piv={}
 for D in ds:
  v={(i,w):x%p for i,d in enumerate(D) for w,x in d.items() if x%p}
  while v:
   k=min(v)
   if k not in piv:
    z=pow(v[k],-1,p);piv[k]={i:x*z%p for i,x in v.items()};break
   u=piv[k];z=v[k]
   for i,x in u.items():
    y=(v.get(i,0)-z*x)%p
    if y:v[i]=y
    elif i in v:del v[i]
 return len(piv)
if __name__=='__main__':
 G=generators(3)
 B=[dbracket(x,y) for i,x in enumerate(G) for y in G[i+1:]]
 C=[dbracket(x,y) for x in G for y in B]
 print('rank degree1,2,3 over F_1000003:',rank(G),rank(B),rank(C))
 import os
 os.makedirs('workspace',exist_ok=True)
 open('workspace/agent3_johnson_ranks.py','w').write(open(__file__).read())

